from taf.config.testline import TestLine

from taf.rfrl.procedures.resources.python.config_validator.Config import Config
from taf.rfrl.procedures.resources.python.logger import log_operation, log_result


def validate_default_init(default_tl: TestLine):
    """
    Validates content of testline configuration from default init file.
    :param default_tl: testline configuration from default init file
    """
    log_operation("Validating default init file")
    config = Config(default_tl)
    config.validate()
    log_result("Validation of default init file succeeded")


def validate_custom_init(default_tl: TestLine, custom_tl: TestLine):
    """
    Validates content of testline configuration from custom init file and
    checks, whether it is a subset of testline configuration from default init file.
    :param default_tl: testline configuration from default init file
    :param custom_tl: testline configuration from custom init file
    """
    log_operation("Validating custom init file")
    default_config, custom_config = Config(default_tl), Config(custom_tl)
    custom_config.validate()
    assert default_config >= custom_config, "Custom init file contains data that is not present in default init file"
    log_result("Validation of custom init file succeeded")
